import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { ScrollArea } from "@/registry/erbium/ui/scroll-area";

export default function CspProviderShowcaseExample() {
  return (
    <CSPProvider disableStyleElements>
      <ScrollArea className="h-40 w-72" aria-label="Scrollable example">
        {Array.from({ length: 12 }, (_, index) => (
          <p key={index} className="p-3">
            Scrollable item {index + 1}
          </p>
        ))}
      </ScrollArea>
    </CSPProvider>
  );
}

import CspProviderShowcaseExample from "../examples/csp-provider-demo";

const Example = () => <CspProviderShowcaseExample />;

export default Example;
